// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Liveness probe
	// (GET /healthz)
	CalendarServiceHealth(ctx context.Context, request CalendarServiceHealthRequestObject) (CalendarServiceHealthResponseObject, error)
	// List bookings in the scope of the caller
	// (GET /v1/bookings)
	ListBookings(ctx context.Context, request ListBookingsRequestObject) (ListBookingsResponseObject, error)
	// Book an appointment (UF-05, UF-06, UF-08)
	// (POST /v1/bookings)
	CreateBooking(ctx context.Context, request CreateBookingRequestObject) (CreateBookingResponseObject, error)
	// Show a booking including reason and infos
	// (GET /v1/bookings/{bookingId})
	GetBooking(ctx context.Context, request GetBookingRequestObject) (GetBookingResponseObject, error)
	// Change or reschedule a booking (UF-06, UF-08)
	// (PATCH /v1/bookings/{bookingId})
	UpdateBooking(ctx context.Context, request UpdateBookingRequestObject) (UpdateBookingResponseObject, error)
	// Cancel a booking (UF-07, UF-08)
	// (POST /v1/bookings/{bookingId}/cancel)
	CancelBooking(ctx context.Context, request CancelBookingRequestObject) (CancelBookingResponseObject, error)
	// Assign a doctor, e.g. for "Sonstiges" (UF-06)
	// (PUT /v1/bookings/{bookingId}/doctor)
	AssignBookingDoctor(ctx context.Context, request AssignBookingDoctorRequestObject) (AssignBookingDoctorResponseObject, error)
	// Bookable start times for a service (UF-05, UF-06)
	// (GET /v1/calendar/availability)
	GetAvailability(ctx context.Context, request GetAvailabilityRequestObject) (GetAvailabilityResponseObject, error)
	// Free and busy blocks without details (UF-05, UF-08)
	// (GET /v1/calendar/blocks)
	GetCalendarBlocks(ctx context.Context, request GetCalendarBlocksRequestObject) (GetCalendarBlocksResponseObject, error)
	// List doctors with their specialties
	// (GET /v1/doctors)
	ListDoctors(ctx context.Context, request ListDoctorsRequestObject) (ListDoctorsResponseObject, error)
	// Specialties and working days of a doctor
	// (GET /v1/doctors/{doctorId}/schedule)
	GetDoctorSchedule(ctx context.Context, request GetDoctorScheduleRequestObject) (GetDoctorScheduleResponseObject, error)
	// Replace specialties and working days of a doctor (UF-09)
	// (PUT /v1/doctors/{doctorId}/schedule)
	UpdateDoctorSchedule(ctx context.Context, request UpdateDoctorScheduleRequestObject) (UpdateDoctorScheduleResponseObject, error)
	// Search patients (UF-08)
	// (GET /v1/patients)
	ListPatients(ctx context.Context, request ListPatientsRequestObject) (ListPatientsResponseObject, error)
	// Assign or remove the main doctor (UF-08)
	// (PUT /v1/patients/{patientId}/main-doctor)
	SetMainDoctor(ctx context.Context, request SetMainDoctorRequestObject) (SetMainDoctorResponseObject, error)
	// List the Leistungsangebot
	// (GET /v1/services)
	ListServices(ctx context.Context, request ListServicesRequestObject) (ListServicesResponseObject, error)
	// Create a service (UF-09)
	// (POST /v1/services)
	CreateService(ctx context.Context, request CreateServiceRequestObject) (CreateServiceResponseObject, error)
	// Import a JSON template (UF-09)
	// (POST /v1/services/import)
	ImportServices(ctx context.Context, request ImportServicesRequestObject) (ImportServicesResponseObject, error)
	// Delete a service (UF-09)
	// (DELETE /v1/services/{serviceId})
	DeleteService(ctx context.Context, request DeleteServiceRequestObject) (DeleteServiceResponseObject, error)
	// Replace a service (UF-09)
	// (PUT /v1/services/{serviceId})
	UpdateService(ctx context.Context, request UpdateServiceRequestObject) (UpdateServiceResponseObject, error)
	// List specialties (Fachrichtungen)
	// (GET /v1/specialties)
	ListSpecialties(ctx context.Context, request ListSpecialtiesRequestObject) (ListSpecialtiesResponseObject, error)
	// Create a specialty (UF-09)
	// (POST /v1/specialties)
	CreateSpecialty(ctx context.Context, request CreateSpecialtyRequestObject) (CreateSpecialtyResponseObject, error)
	// Delete a specialty (UF-09)
	// (DELETE /v1/specialties/{specialtyId})
	DeleteSpecialty(ctx context.Context, request DeleteSpecialtyRequestObject) (DeleteSpecialtyResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

